pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        c.XBornID();
        uint256 distrBefore = c.totalDistributed();
        vm.prank(actor);
        c.getTokens();
        uint256 distrDelta = c.totalDistributed() - distrBefore;
        assertTrue(c.balanceOf(actor) == distrDelta);
    }
}
